const f = $('Get facts').first().json;
const label = { runs: '실행', alerts: '알림', dlq: 'DLQ', quality: '데이터 품질', cost: '비용', release: '릴리스' };
const mark = { red: '🔴', yellow: '🟡', green: '🟢', unknown: '⚪' };
const actionsFor = {"runs": "오류 묶음 1위 확인 · 고치기 (77일차)", "alerts": "높은 알림부터 확인하고 닫기 (76일차)", "dlq": "parked 건 원인 확인 뒤 런북대로 재처리 (76일차)", "quality": "격리함을 콘텐츠 담당자에게 (78일차)", "cost": "비용 1위 사용자 · 한도 확인 (75일차)", "release": "카나리 끄기 · 되돌리기 검토 (74일차)"};
const pct = (v) => (Math.round(v * 10000) / 100) + '%';
const g = (k, fn) => (f[k] === null ? '출처 응답 없음' : fn());
const key = {
  runs: g('runs', () => `오류율 ${pct(f.runs.error_rate)} · p95 ${f.runs.p95_ms}ms · 답 못 함 ${pct(f.runs.unanswered_rate)}`),
  alerts: g('alerts', () => `${f.alerts.count}건 (높음 ${f.alerts.high})`),
  dlq: g('dlq', () => `${f.dlq.size}건 (parked ${f.dlq.parked})`),
  quality: g('quality', () => `평균 ${f.quality.avg_score} · 마지막 ${f.quality.last_score} · 격리 ${f.quality.quarantine}`),
  cost: g('cost', () => `$${f.cost.cost_usd} / $${f.cost.daily_usd} (${pct(f.cost.used_ratio)})`),
  release: g('release', () => `${f.release.active}` + (f.release.canary_release ? ` · 카나리 ${f.release.canary_release} ${f.release.canary_percent}% (다시 묻기 ${f.release.canary_repeat_rate === null ? '-' : pct(f.release.canary_repeat_rate)})` : '')),
};
const order = ['runs', 'alerts', 'dlq', 'quality', 'cost', 'release'];
const focus = [...f.red, ...f.yellow].slice(0, 3);
const actions = focus.map((k) => ({ area: k, status: f.health[k], action: actionsFor[k] }));
const lines = [
  `# 운영 브리핑 (${f.period.from} ~ ${f.period.to} 실행 기록 + 지금 상태)`, '',
  `전체: ${mark[f.overall]} ${f.overall}`, '',
  '| 영역 | 상태 | 숫자 |', '| --- | --- | --- |',
  ...order.map((k) => `| ${label[k]} | ${mark[f.health[k]]} | ${key[k]} |`), '',
  '## 먼저 볼 것', '',
  ...actions.map((a, i) => `${i + 1}. ${mark[a.status]} ${label[a.area]}: ${a.action}`),
];
return [{ json: { overall: f.overall, red: f.red, yellow: f.yellow, actions, markdown: lines.join('\n'), facts: f } }];
